\label{standard_Schrodinger_Carleman_estimate_0}
Let $p(x) \in L^{\infty}(\Omega)$ with $\Vert p\Vert_{L^{\infty}(\Omega)} \leq M$ for some $M > 0$. Picking a point $x_{0} \notin \overline{\Omega}$ and $T^{*} \in (0, T)$, define $\psi(x) = |x - x_{0}|^{2}$ and
\begin{equation}
\phi(x,t) =  \frac{e^{2\lambda\Vert \psi\Vert_{\infty}} - e^{\lambda \psi(x)}}{(T^{*})^{2}-t^{2}}
\end{equation}
on $\Omega \times (-T^{*},T^{*})$, where $\Vert \psi \Vert_{\infty} = \Vert \psi \Vert_{L^{\infty}(\Omega)}$. Now, there exist $\lambda_{*} = \lambda_{*}(\Omega, T^{*}, \Omega_{1}, \Omega_{2}) > 0,\, s_{*} = s_{*}(\Omega, T^{*}, \Omega_{1}, \Omega_{2}) > 0$ such that for all $\lambda \geq \lambda_{*},\, s \geq s_{*},$ and a constant $C = C(M,\Omega, T^{*}, s_{*},\lambda_{*}) > 0$,
\begin{equation} \label{OldCarlemanEstimate_2}
\begin{split}
s^3 \lambda^4\Vert e^{-s\phi}u\Vert_{L^2(\Omega_{2} \times (-T^{*},T^{*}))}^2 + s\lambda\Vert e^{-s\phi}\nabla u\Vert_{L^2(\Omega_{2} \times (-T^{*},T^{*}))}^2
\leq
C\Vert e^{-s\phi} Lu\Vert_{L^2(\Omega \times (-T^{*},T^{*}))}^2 \\ 
+\; C\left(s^3 \lambda^4\Vert e^{-s\phi}u\Vert_{L^2(\Omega_{3} \setminus \Omega_{2} \times (-T^{*},T^{*}))}^2 + s\lambda\Vert e^{-s\phi}\nabla u\Vert_{L^2(\Omega_{3} \setminus \Omega_{2} \times (-T^{*},T^{*}))}^2 \right).
\end{split}
\end{equation}
The above holds for $u \in L^{2}\left(-T^{*},T^{*};\,H^{1}_{0}(\Omega) \right)$ such that $Lu \in L^{2}\left(\Omega \times (-T^{*},T^{*})\right)$.
